const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));
const ease=x=>x*x*(3-2*x);
export function storyFrame(entry,time,reduced=false){const shots=entry.shots||[],duration=entry.duration||7,span=duration/Math.max(1,shots.length),index=Math.min(shots.length-1,Math.floor(time/span)),p=clamp((time-index*span)/span);return {shot:shots[index],index,p:reduced?.5:ease(p),fade:reduced?1:clamp(time/.45)*clamp((duration-time)/.55),transition:reduced?0:clamp((.20-p)*5)};}
function cover(c,image,focus,zoom){const W=1280,H=720,iw=image.videoWidth||image.naturalWidth||image.width,ih=image.videoHeight||image.naturalHeight||image.height,scale=Math.max(W/iw,H/ih)*zoom,w=iw*scale,h=ih*scale,x=clamp(W/2-w*focus[0],W-w,0),y=clamp(H/2-h*focus[1],H-h,0);c.drawImage(image,x,y,w,h);}
/** Shot camera and physically placed weather/light cues; no image or actor is rotated. */
export function drawExpansion(d,time){const c=d.ctx,e=d.entry,quiet=d.reduced||!!d.renderer?.compatibility,frame=storyFrame(e,time,quiet),shot=frame.shot;if(!shot)return;const W=1280,H=720;c.save();c.setTransform(d.canvas.width/W,0,0,d.canvas.height/H,0,0);c.fillStyle='#050b13';c.fillRect(0,0,W,H);const art=d.image(shot.art)||d.image(e.shots[0].art),move=quiet?0:1;let video=d.motionMedia?.frame({reduced:d.reduced,compatibility:!!d.renderer?.compatibility});if(video)try{cover(c,video,[.5,.5],1);}catch{d.motionMedia?.dispose();video=null;}if(!video&&art){const focus=[shot.focus[0]+Math.sin(frame.p*Math.PI)*.018*move,shot.focus[1]],z=shot.zoom+frame.p*.035*move;cover(c,art,focus,z);}
else if(!video&&d.backdrop?.complete&&d.backdrop.naturalWidth)c.drawImage(d.backdrop,0,0,W,H);
const weather=shot.art.includes('concord')||e.chapter===9?'rain':shot.art.includes('wayglass')?'water':e.topic==='household'?'steam':null;
if(!video&&move&&weather==='rain'){c.save();c.strokeStyle='#d3e6f3';c.globalAlpha=.15;c.lineWidth=1.1;for(let i=0;i<65;i++){const x=(i*173+time*75)%W,y=(i*91+time*390)%H;c.beginPath();c.moveTo(x,y);c.lineTo(x-8,y+24);c.stroke();}c.restore();}
if(!video&&weather==='water'){c.save();c.globalCompositeOperation='screen';const glow=c.createRadialGradient(535,372,10,535,372,250);glow.addColorStop(0,'#b4ebcc22');glow.addColorStop(1,'#b4ebcc00');c.fillStyle=glow;c.globalAlpha=.7+Math.sin(time*1.7)*.15*move;c.fillRect(280,100,520,500);c.strokeStyle='#addbd5';c.lineWidth=1.1;for(let i=0;i<4;i++){c.globalAlpha=(.11-i*.018)*(1+Math.sin(time*1.4+i)*.25*move);c.beginPath();c.ellipse(865,427,75+i*31+Math.sin(time+i)*2*move,8+i*4,0,0,Math.PI*2);c.stroke();}c.restore();}
if(!video&&move&&weather==='steam'){c.save();c.strokeStyle='#f6d4a3';c.lineWidth=2;c.globalAlpha=.075;for(let i=0;i<3;i++){c.beginPath();c.moveTo(810+i*13,510);c.bezierCurveTo(785+i*15,475,835+i*14+Math.sin(time)*9,465,809+i*13,430);c.stroke();}c.restore();}
if(e.frontierPortrait){c.save();if(e.hue&&!quiet)c.filter='hue-rotate('+e.hue+'deg)';const height=e.compact?310:390,bob=quiet?0:Math.sin(time*1.9)*3;d.sprite(e.atlas,e.sprite,0,910,590+bob,height);c.restore();}
// Fine lens falloff retains texture and readable painted faces.
const vignette=c.createRadialGradient(640,330,240,640,360,780);vignette.addColorStop(0,'#02091400');vignette.addColorStop(1,'#0209149a');c.fillStyle=vignette;c.fillRect(0,0,W,H);const shade=c.createLinearGradient(0,430,0,720);shade.addColorStop(0,'#03091400');shade.addColorStop(1,'#030914e8');c.fillStyle=shade;c.fillRect(0,430,W,290);if(frame.transition&&frame.index){c.fillStyle='#050a12';c.globalAlpha=frame.transition*.8;c.fillRect(0,0,W,H);c.globalAlpha=1;}if(frame.fade<1){c.fillStyle='#030811';c.globalAlpha=1-frame.fade;c.fillRect(0,0,W,H);c.globalAlpha=1;}if(!e.compact){c.fillStyle='#030811';c.fillRect(0,0,W,28);c.fillRect(0,692,W,28);c.fillStyle='#decf9a88';c.fillRect(75,655,80,1);}
c.restore();if(d.storyShotIndex!==frame.index){d.storyShotIndex=frame.index;d.root.querySelector('.cinematic-copy p').textContent=shot.caption;d.root.querySelector('.cinematic-copy small').textContent=e.compact?'A MOMENT REMEMBERED':'CLAY & WATER · '+(frame.index+1)+' / '+e.shots.length;}}
